mapper.select:
SELECT  FROM sr_account
WHERE username = #{identifier} OR email = #{identifier}
LIMIT 1

mapper.update:
UPDATE sr_account_credential
SET password_hash = #{passwordHash}, password_changed_at = CURRENT_TIMESTAMP(3)
WHERE account_id = #{accountId}

mapper.select:
SELECT DISTINCT r.code FROM sr_account_role ar
JOIN sr_role r ON r.id = ar.role_id AND r.status = 'ENABLED'
WHERE ar.account_id = #{accountId}

mapper.update:
UPDATE sr_admin_invitation SET token_hash = #{tokenHash}, expires_at = #{expiresAt}, status = 'PENDING',
    last_sent_at = #{lastSentAt}, mail_message_id = #{mailMessageId}, mail_submission_status = 'SUBMITTED'
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM sr_account_audit
WHERE action_code = 'PASSWORD_RESET_REQUESTED' AND ip_address = #{ip}
  AND created_at >= #{since}

SELECT COUNT(*) FROM sr_account_audit
WHERE action_code = #{action} AND ip_address = #{ip}
  AND created_at >= #{since}
